pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Make actor a depositor with credit
        uint256 creditBefore = c.credit(actor);

        // Re-entrant attacker that calls withdrawAll during receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 0);

        vm.prank(actor);
        c.withdrawAll();

        // After any withdrawal, credit[actor] should be 0, and balance >= 0
        // The bug keeps balance artificially high, but invariants fail later.
        // Here we check a direct invariant: contract balance >= total credit.
        // Since we have only one depositor, total credit = credit[actor] which is 0.
        // The bug causes balance > 0, making balance >= credit true, so this invariant
        // won't break. We need a different invariant.

        // After withdrawal, balance must be 0 because all credit subtracted.
        // Bug leaves balance unchanged, so balance == depositAmount, violating:
        // address(c).balance == 0
        assertTrue(address(c).balance == 0);
    }
}

