pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 recipientSeed) public {
        // bound deposit to a reasonable range to keep the fuzzer efficient, but wide enough to find the bug
        depositAmount = bound(depositAmount, 1, 100 ether);
        // derive a deterministic recipient address from the seed (not msg.sender, which is the test contract)
        address recipient = address(uint160(uint256(keccak256(abi.encode(recipientSeed)))));
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));

        // deploy an adversarial re-entrant contract that calls withdrawAll again in its receive callback
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund the test contract and deposit into C as the attacker
        vm.deal(attacker, depositAmount);
        vm.prank(attacker);
        c.deposit{value: depositAmount}();

        // attacker triggers the first withdrawal; its receive() will re-enter and call withdrawAll again
        vm.prank(attacker);
        attacker.attack();

        // After the attack completes, the reference contract clears the credit on the first withdrawal,
        // so the re-entrant second withdrawal finds credit == 0 and transfers nothing.
        // The buggy contract does not clear credit, so the attacker receives funds twice.
        // The universal property: the contract's ETH balance must not decrease below its recorded 'balance' state variable.
        // The buggy contract violates this because it subtracts balance only once but transfers twice.
        assertTrue(address(c).balance >= c.balance());
    }
}

contract ReentrantAttacker {
    C target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack() external {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            target.withdrawAll();
        }
    }
}

