pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackerSeed) public {
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        // Deploy a re-entrant attacker that withdraws twice.
        ReentrantAttacker attacker = new ReentrantAttacker(c, attackerSeed);
        vm.deal(address(attacker), depositAmount);
        // Fund the attacker and make it deposit.
        vm.prank(address(attacker));
        attacker.deposit{value: depositAmount}();
        // Record state before the triggered withdrawal.
        uint256 contractBalanceBefore = address(c).balance;
        uint256 attackerBalanceBefore = address(attacker).balance;
        uint256 totalCreditsBefore = c.credit(address(attacker)); // via auto-generated getter
        // The attacker's deposit() already gives it a credit equal to depositAmount.
        // Now trigger the withdrawal sequence: attacker calls withdrawAll, which re-enters and withdraws a second time.
        vm.prank(address(attacker));
        attacker.attack();
        // After the attack, the buggy contract allows the attacker to withdraw its credit twice,
        // draining more ETH than it should. The correct contract zeroes credit on the first withdrawal,
        // so the second withdrawal fails the `if (oCredit > 0)` check.
        uint256 contractBalanceAfter = address(c).balance;
        uint256 attackerBalanceAfter = address(attacker).balance;
        uint256 totalCreditsAfter = c.credit(address(attacker));
        // The reference C satisfies: the attacker's total received ETH equals exactly its initial deposit,
        // contract balance decreases by exactly that amount, and attacker's credit is zero.
        // Buggy M: attacker receives 2*deposit, contract balance decreases by 2*deposit, credit remains >0.
        // Universal rule for reference: after a full attack sequence (deposit + attack),
        // the contract balance change equals the attacker's net ETH gain (which is exactly depositAmount),
        // and the attacker's credit is zero.
        assertTrue(
            (attackerBalanceAfter - attackerBalanceBefore) == depositAmount &&
            (contractBalanceBefore - contractBalanceAfter) == depositAmount &&
            totalCreditsAfter == 0
        );
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public immutable seed;
    bool private attacking;

    constructor(C _target, uint256 _seed) {
        target = _target;
        seed = _seed;
    }

    function deposit() external payable {
        target.deposit{value: msg.value}();
    }

    function attack() external {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Re-enter with minimal gas, performing a second withdrawal.
            target.withdrawAll();
        }
    }
}

