pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amountA, uint256 amountB, uint256 amountC) public {
        // Bound amounts to avoid overflow and insolvency
        amountA = bound(amountA, 1, type(uint128).max);
        amountB = bound(amountB, 1, type(uint128).max);
        amountC = bound(amountC, 1, type(uint128).max);

        // Deploy an adversarial receiver that re-enters withdrawAll again when receiving ETH
        // This reveals the bug: it can extract credits multiple times in one transaction
        ReentrantReceiver receiver = new ReentrantReceiver(c);

        // Fund addresses
        address alice = makeAddr("alice");
        vm.deal(alice, amountA + amountB + amountC);
        vm.deal(address(receiver), 0);

        // Alice deposits once, then receiver gets a different credit via deposit
        vm.prank(alice);
        c.deposit{value: amountA}();

        // receiver deposits its own credits
        vm.deal(address(receiver), amountB);
        vm.prank(address(receiver));
        c.deposit{value: amountB}();

        // Alice deposits another amount to vary credits
        vm.prank(alice);
        c.deposit{value: amountC}();

        // Record pre-conditions
        uint256 preBalance = address(c).balance;
        uint256 preCreditReceiver = c.credit(address(receiver));
        uint256 preCreditAlice = c.credit(alice);
        uint256 preSumCredits = preCreditReceiver + preCreditAlice;

        // Receiver triggers withdrawal; the re-entrant attack extracts extra ETH if buggy
        vm.prank(address(receiver));
        receiver.attack(0);

        // Invariant: total ETH balance must equal the sum of remaining credits
        // after all operations (no external initial funding assumed).
        uint256 postBalance = address(c).balance;
        uint256 postCreditReceiver = c.credit(address(receiver));
        uint256 postCreditAlice = c.credit(alice);
        uint256 postSumCredits = postCreditReceiver + postCreditAlice;

        assertTrue(postBalance == postSumCredits);
    }
}

contract ReentrantReceiver {
    C public target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 /* dummy */) external {
        require(!attacking, "already attacking");
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }

    receive() external payable {
        if (!attacking && address(target).balance >= 0) {
            attacking = true;
            target.withdrawAll();
            attacking = false;
        }
    }
}

