pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address caller) public {
        vm.assume(depositAmount > 0);
        vm.assume(caller != address(0));
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Adversarial counterparty: a contract that reverts on receiving any ETH,
        // because the buggy version always makes a low-level call even with zero credit.
        Reverter reverter = new Reverter();
        vm.deal(reverter, 0);

        bool ok;
        vm.prank(reverter);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // With a positive credit, the correct contract sends ETH to the caller (which reverts) and the whole
        // call reverts.  The assertion: a non-reverting withdrawAll from the Reverter implies credit[Reverter]==0
        // (which only happens when credit was zero – but then the reference reverts on the non-zero send).
        // Actually, the reference always reverts when credit>0 because the receiver reverts.
        // The reference can only succeed when credit==0, which means the Reverter never had a deposit.
        // The buggy version always executes the body: if credit>0 it reverts on the send (same as reference),
        // but if credit==0 it also executes the body and reverts on the zero-value send.
        // So for the Reverter with positive credit, both revert. For the Reverter with zero credit, reference
        // succeeds (skips body), buggy reverts (executes body, zero-value send reverts).
        // Rule: if withdrawAll does not revert, credit[Reverter] must be 0.
        assertTrue(!ok || c.credit(reverter) == 0);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

