pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Keep amounts within a reasonable range to avoid overflow on addition
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);
        vm.assume(depositAmount > 0);

        // An actor that will just deposit and withdraw successfully.
        // We need an EOA, so we use a precomputed address that is not this contract.
        address alice = address(0x1234);
        vm.deal(alice, depositAmount);
        vm.prank(alice);
        c.deposit{value: depositAmount}();

        // Record balance before any withdrawal.
        uint256 balanceBefore = address(c).balance;

        // Now attempt to withdraw a specific amount as a different actor (bob).
        // Bob has zero credit; a call to withdrawAll should either revert or succeed and do nothing.
        address bob = address(0x5678);
        bool ok;
        vm.prank(bob);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the contract balance MUST remain unchanged because bob had no credit.
        // This holds on the reference C (where the if-guard prevents any state change),
        // but the buggy M always executes the body, causing a zero-value call that succeeds (to an EOA),
        // yet balance-=0 and credit=0 change nothing 
        // Wait, the buggy version's body does execute and can succeed on an EOA, but it still does not change balance.
        // We need a property that actually breaks. The prior attempts were rejected, so we need to
        // construct an adversarial callee that reverts on zero-value calls.
        // But the instructions say the fuzzer CANNOT synthesise that party; we MUST deploy a helper.
    }
}

contract RevertingReceiver {
    fallback() external payable {
        require(msg.value > 0, "zero value rejection");
    }
